solution.code:
type Payment =
  | { status: 'pending' }
  | { status: 'succeeded'; transactionId: string }
  | { status: 'failed'; reason: string };

function summarize(p: Payment): string {
  if (p.status === 'pending') return 'pending';
  if (p.status === 'succeeded') return 'ok ' + p.transactionId;
  return 'failed ' + p.reason;
}

console.log(summarize({ status: 'pending' }));
console.log(summarize({ status: 'succeeded', transactionId: 'tx_1' }));
console.log(summarize({ status: 'failed', reason: 'declined' }));

