// Wanted: Status is exactly 'on' | 'off'
// interface can't express a union, so this drifts to a plain string:
interface Settings { status: string; }

function toggle(s: Settings): string {
  // typo 'of' is NOT caught because status is just string
  return s.status === 'of' ? 'turning on' : 'turning off';
}

console.log(toggle({ status: 'off' }));

solution.code:
type Status = 'on' | 'off';
interface Settings { status: Status; }

function toggle(s: Settings): string {
  // comparing against 'of' is now a compile error
  return s.status === 'on' ? 'turning off' : 'turning on';
}

console.log(toggle({ status: 'off' }));

